SELECT DATE_FORMAT(s.opened_date, 'yyyy-MM') AS opened_month, MAX(o.order_date) AS last_order_date, SUM(CASE WHEN o.status = 'CANCELLED' THEN o.discount ELSE 0 END) AS cancelled_discount FROM orders o JOIN customers c ON o.customer_id = c.id LEFT OUTER JOIN stores s ON o.store_id = s.id WHERE s.city = 'London' GROUP BY DATE_FORMAT(s.opened_date, 'yyyy-MM') ORDER BY last_order_date DESC, cancelled_discount DESC, opened_month LIMIT 50;
